'use strict';
// Модуль «Моя организация»
/* ═════════════ Моя организация ═════════════ */
// Реквизиты для приёма денег (решение заказчика 25.10.2026): «Расчётный счёт» или «Перевод по номеру телефона», назначение и основной для налогов и для обслуживания
const rqMainPill=(t,on)=>on?pill(t,{[t]:['green','star']}):'';
const orgAccRows=()=>ORG.accounts.map((a,i)=>`<tr><td>${a.kind==='phone'?ic('phone','sm'):ic('building','sm')} ${esc(rqKindL(a,1))}</td><td>${esc(rqProv(a))}</td><td class="mono">${esc(rqNum(a))}${a.kind!=='phone'&&a.bik?`<div class="hint">БИК ${esc(a.bik)}</div>`:''}</td><td>${esc(a.name||'—')}</td><td>${esc(RQ_USE_L[a.use||'both'])}</td><td>${rqMainPill('Основной для налогов',a.mainTax&&accUse(a,'tax'))} ${rqMainPill('Основной для обслуживания',a.mainFee&&accUse(a,'fee'))}</td>${can('org')?`<td style="white-space:nowrap"><button type="button" class="icon-btn sm" data-acc-e="${i}" title="Изменить" aria-label="Изменить счёт">${ic('edit','sm')}</button><button type="button" class="icon-btn sm" data-acc-d="${i}" title="Удалить" aria-label="Удалить счёт">${ic('trash','sm')}</button></td>`:''}</tr>`).join('')||`<tr><td colspan="7" class="muted">Счетов пока нет</td></tr>`;
const orgAccHead=()=>`<thead><tr><th>Вид</th><th>Банк или кошелёк</th><th>Номер</th><th>Получатель</th><th>Назначение</th><th>Основной</th>${can('org')?'<th></th>':''}</tr></thead>`;
function orgAccDlg(a,done){const ed=!!a;const st={k:a?a.kind||'acc':'acc'};const first=!ORG.accounts.length;
  openModal({form:true,render:()=>({title:ed?'Изменить счёт организации':'Счёт организации',sub:'Куда контрагенты переводят деньги на налоги и за обслуживание',body:`<div class="form">${fld('Вид',rqKindSel('oa-k',st.k,1),{full:true,id:'oa-k'})}
    <div class="fld full rq-g" data-rqg="acc" ${st.k==='acc'?'':'hidden'}><div class="form">${fld('Банк',sel('oa-b',rqProvs(false,a&&a.bank?[a.bank]:[]),a&&a.bank||'Optima Bank'),{req:true,id:'oa-b'})}${fld('БИК',inp('oa-bik',a&&a.bik||'','class="inp mono" inputmode="numeric" maxlength="6"'),{req:true,id:'oa-bik'})}${fld('Расчётный счёт',inp('oa-acc',a&&a.acc||'','class="inp mono" inputmode="numeric"'),{req:true,full:true,id:'oa-acc'})}</div></div>
    <div class="fld full rq-g" data-rqg="phone" ${st.k==='phone'?'':'hidden'}><div class="form">${fld('Номер телефона',phoneInput('oa-ph',a&&a.phone||null),{req:true,id:'oa-ph'})}${fld('Банки и кошельки, к которым привязан номер',rqBanksFld('oa-bs',a&&a.banks||[]),{req:true,full:true,id:'oa-bs',hint:'По номеру переводят внутри одного банка или кошелька, поэтому отметьте все, где открыт этот номер. В списке — только провайдеры с переводами по номеру телефона.'})}</div></div>
    ${fld('Получатель',inp('oa-name',a?a.name||'':ORG.name),{full:true,id:'oa-name',hint:'Так, как его видит отправитель в приложении банка, например «ОсОО Ахти»'})}${fld('Назначение',sel('oa-use',RQ_USE,a&&a.use||'both'),{id:'oa-use',hint:'Для чего контрагенты переводят на этот счёт'})}</div>
    <label class="check-row" data-rqm="tax"><input type="checkbox" class="sw" id="oa-mt" ${a?a.mainTax?'checked':'':first?'checked':''}><span class="grow">Основной для налогов<div class="hint">Подставляется в напоминания о налогах и в «Как оплатить» на странице контрагентов, которые переводят деньги на налоги на счёт организации</div></span></label>
    <label class="check-row" data-rqm="fee"><input type="checkbox" class="sw" id="oa-mf" ${a?a.mainFee?'checked':'':first?'checked':''}><span class="grow">Основной для обслуживания<div class="hint">Подставляется в напоминание о долге за обслуживание и в «Как оплатить»</div></span></label>`,
    foot:`<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="oa-ok">${ed?'Сохранить':'Добавить'}</button>`,
    mount(el,m){bindPhone(el,'oa-ph');const useUpd=()=>{const u=val(el,'oa-use');$$('[data-rqm]',el).forEach(x=>x.hidden=!accUse({use:u},x.dataset.rqm))};useUpd();$('#oa-use',el).onchange=useUpd;
      $('#oa-k',el).onclick=e=>{const b=e.target.closest('[data-rqk]');if(!b)return;st.k=b.dataset.rqk;$$('[data-rqk]',el).forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b)});$$('[data-rqg]',el).forEach(g=>g.hidden=g.dataset.rqg!==st.k)};
      $('#oa-ok',el).onclick=()=>{let ok,ph,bs;if(st.k==='acc')ok=[setErr(el,'oa-acc',val(el,'oa-acc').replace(/\D/g,'').length>=16?'':'Счёт — 16 цифр'),setErr(el,'oa-bik',/^\d{6}$/.test(val(el,'oa-bik'))?'':'БИК — 6 цифр')].every(Boolean);
        else{const p=readPhone(el,'oa-ph');ph=p.ph;bs=rqBanksRead(el,'oa-bs');ok=[setErr(el,'oa-ph',p.ok?'':`Введите номер полностью: ${p.need} цифр после кода страны`),setErr(el,'oa-bs',bs.length?'':'Отметьте хотя бы один банк или кошелёк')].every(Boolean)}if(!ok)return;
        const x=a||{};const old=a?rqTxt(a):'';if(st.k==='acc'){Object.assign(x,{kind:'acc',bank:val(el,'oa-b'),acc:val(el,'oa-acc'),bik:val(el,'oa-bik')});delete x.phone;delete x.banks}else{Object.assign(x,{kind:'phone',phone:ph,banks:bs});delete x.bank;delete x.acc;delete x.bik}
        Object.assign(x,{name:val(el,'oa-name'),use:val(el,'oa-use')});const mt=$('#oa-mt',el).checked&&accUse(x,'tax'),mf=$('#oa-mf',el).checked&&accUse(x,'fee');if(mt)ORG.accounts.forEach(y=>y.mainTax=false);if(mf)ORG.accounts.forEach(y=>y.mainFee=false);x.mainTax=mt;x.mainFee=mf;delete x.main;
        if(!a)ORG.accounts.push(x);rqMainFix();log('org','accounts',a?`Изменён счёт ${old} → ${rqTxt(x)}`:`Добавлен счёт ${rqTxt(x)}`);m.close();done&&done();toast(a?'Счёт изменён':'Счёт добавлен')}}})})}
// «Сдача отчётов требует подтверждения»: при выключении ждущие отчёты считаются подтверждёнными (с записью в истории), при включении уже сданные не начинают ждать заново
function repConfSet(x){const on=x.checked;const w=REPORTS.filter(r=>repWait(r));
  const apply=()=>{if(!on)w.forEach(r=>{Object.assign(r,{confAt:nowStamp(),confBy:S.me,confNote:'Подтверждение выключено в учётной политике'});log('r',r.id,'Сдача подтверждена (Подтверждение выключено в учётной политике)',r.cp)});
    else REPORTS.forEach(r=>{if(r.status==='Сдан'&&!r.confAt&&!tR(r).payOnly)Object.assign(r,{confAt:nowStamp(),confBy:null,confNote:'Сдан, когда подтверждение было выключено'})});
    ORG.repConfirm=on;log('org','policy',`Сдача отчётов требует подтверждения: ${on?'включено':'выключено'}${!on&&w.length?`; считаются подтверждёнными: ${w.length}`:''}`);refreshAll();toast(on?'Сданные отчёты будут ждать подтверждения':'«Сдан» теперь окончательная отметка')};
  if(!on&&w.length){x.checked=true;return confirmDlg({title:'Выключить подтверждение сдачи?',text:`${w.length} ${plural(w.length,'отчёт ждёт','отчёта ждут','отчётов ждут')} подтверждения: они будут считаться подтверждёнными, в истории статусов появится запись «Подтверждение выключено в учётной политике».`,ok:'Выключить',run:apply})}
  apply()}
// Разделы страницы контрагента — под переключателем «Страница контрагента по ссылке»
function pgPolHtml(ro){return `<div class="pg-pol"><span class="hint">Разделы страницы для всех контрагентов; у отдельного контрагента раздел можно скрыть в его карточке. «Ваш бухгалтер» видно всегда.</span>${PG_SECS.map(([k,l,f])=>{const off=f&&!feat(f);return `<label class="check-row"><input type="checkbox" data-pg-pol="${k}" ${(ORG.pageSec||[]).includes(k)?'checked':''} ${ro||off?'disabled':''}><span class="grow">${esc(l)}${off?`<div class="hint">Появится на странице, когда включена функция «${esc(FEATURES.find(x=>x[0]===f)[1])}»</div>`:''}</span></label>`}).join('')}</div>`}
// Занятые слова — адреса самой программы: ссылки контрагентов не должны пересекаться с ними (v58)
const SLUG_BUSY=['api','admin','login','logout','auth','signup','register','reset','password','test','www','inn','app','help','support','docs','static','assets','files','mail','status','staging','dev','demo','buhuchet'],SLUG_BUSY_T='Этот адрес занят, выберите другой';
const slugErr=v=>!/^[a-z0-9-]{3,30}$/.test(v)?'3–30 символов: строчные латинские буквы, цифры и дефис':SLUG_BUSY.includes(v)?SLUG_BUSY_T:ORGS.some(o=>!o.self&&o.slug===v)?'Такой адрес уже занят другой организацией':'';
function renderOrg(body,tab){
  const ro=!can('org');
  if(tab==='main'){
    if(ro){body.innerHTML=`<div class="note">${ic('lock')}<span>Редактировать может только владелец организации. Вы видите профиль только для просмотра.</span></div>${orgMainView()}`;return}
    body.innerHTML=`<div class="box"><h3>Основное</h3><div class="form">${fld('Название',inp('og-name',ORG.name),{req:true,full:true,id:'og-name'})}${fld('ИНН',inp('og-inn',ORG.inn,'class="inp mono" maxlength="14"'),{req:true,id:'og-inn'})}${fld('Телефон',phoneInput('og-ph',ORG.phone),{id:'og-ph'})}${fld('Адрес',inp('og-addr',ORG.address),{full:true,id:'og-addr'})}${fld('Руководитель',inp('og-head',ORG.head),{id:'og-head'})}${feat('cppage')?fld('Адрес страницы организации',inp('og-slug',ORG.slug||'','class="inp mono" maxlength="30" autocapitalize="off" spellcheck="false"'),{req:true,id:'og-slug',hint:`Для ссылок на страницы контрагентов: www.buhuchet.kg/${esc(ORG.slug||'…')}/inn/<ИНН>. 3–30 символов: строчные латинские буквы, цифры и дефис`}):''}${fld('Логотип',`<div class="row" style="flex-wrap:nowrap;gap:10px">${ORG.logo?`<img src="${ORG.logo}" alt="Логотип" style="width:40px;height:40px;object-fit:contain;border-radius:8px;border:1px solid var(--border)">`:''}<input class="inp" type="file" id="og-logo" accept="image/*"></div>`,{id:'og-logo',hint:'PNG или JPG до 2 МБ'})}</div><div class="row"><div class="grow"></div><button class="btn cta" id="og-save">Сохранить</button></div></div>
    <div class="box"><h3>Реквизиты для приёма денег от контрагентов<span class="grow"></span><button class="btn sm" id="og-addacc">${ic('plus','sm')}Добавить счёт</button></h3><div class="tbl-wrap"><table class="mini m-cards">${orgAccHead()}<tbody id="og-accs">${orgAccRows()}</tbody></table></div><span class="hint">Расчётный счёт или перевод по номеру телефона (M-Bank, Бакай Банк, О!Банк и другие). Юрлица часто не могут переводить на карты физлиц — тогда контрагент переводит деньги на налоги сюда; это выбирается в карточке контрагента. Основные счета для налогов и для обслуживания подставляются в напоминания в WhatsApp и в «Как оплатить» на странице контрагента.</span></div>`;
    bindPhone(body,'og-ph');
    {const si=$('#og-slug',body);if(si)si.oninput=()=>setErr(body,'og-slug',SLUG_BUSY.includes(si.value.trim().toLowerCase())?SLUG_BUSY_T:'')}
    $('#og-save').onclick=()=>{const sg=$('#og-slug',body)?val(body,'og-slug').trim().toLowerCase():null;const ok=[setErr(body,'og-name',val(body,'og-name')?'':'Введите название'),setErr(body,'og-inn',/^\d{14}$/.test(val(body,'og-inn'))?'':'ИНН — 14 цифр'),sg==null||setErr(body,'og-slug',slugErr(sg))].every(Boolean);if(!ok)return;
      // Смена адреса: ссылки, отправленные контрагентам, перестанут открываться
      if(sg!=null&&sg!==ORG.slug)return confirmDlg({title:'Сменить адрес страницы организации?',text:`Ссылки, отправленные контрагентам, перестанут открываться. Новые ссылки будут вида www.buhuchet.kg/${esc(sg)}/inn/&lt;ИНН&gt; — их нужно отправить заново.`,ok:'Сменить адрес',danger:true,run:()=>{const o=ORG.slug;ORG.slug=sg;log('org','main',`Адрес страницы организации: ${o} → ${sg}`);saveMain()}});
      saveMain()};
    const saveMain=()=>{ORG.name=val(body,'og-name');ORG.inn=val(body,'og-inn');ORG.address=val(body,'og-addr');ORG.head=val(body,'og-head');const p=readPhone(body,'og-ph');if(p.ok)ORG.phone=p.ph;const lf=$('#og-logo',body).files[0];
      if(lf){if(lf.size>2*1048576){setErr(body,'og-logo','Файл больше 2 МБ');return}const fr=new FileReader();fr.onload=()=>{ORG.logo=fr.result;log('org','main','Загружен логотип');renderPage();renderSide()};fr.readAsDataURL(lf)}
      log('org','main','Изменены основные сведения');renderSide();renderPage();toast('Сохранено')};
    const accRe=()=>{const tb=$('#og-accs');if(tb)tb.innerHTML=orgAccRows()};$('#og-accs').onclick=e=>{const b=e.target.closest('[data-acc-e],[data-acc-d]');if(!b)return;if(b.dataset.accE!=null)return orgAccDlg(ORG.accounts[+b.dataset.accE],accRe);const i=+b.dataset.accD;const a=ORG.accounts[i];const used=CPS.filter(c=>c.paysTo==='org'&&!c.archived).length;const noTax=accUse(a,'tax')&&orgAccs('tax').length===1;
      confirmDlg({title:`Удалить счёт ${esc(rqProv(a))}?`,text:noTax&&used?`Это единственный счёт для налогов, а ${used} ${plural(used,'контрагент переводит','контрагента переводят','контрагентов переводят')} деньги на налоги на счёт организации: в напоминаниях и на их странице не будет реквизитов, пока вы не добавите новый.`:'Счёт пропадёт из реквизитов для контрагентов. Прошлые поступления не меняются.',ok:'Удалить',danger:true,run:()=>{ORG.accounts.splice(i,1);rqMainFix();log('org','accounts',`Удалён счёт ${rqTxt(a)}`);accRe();toast('Счёт удалён')}})};
    $('#og-addacc').onclick=()=>orgAccDlg(null,accRe);
    return}
  if(tab==='policy'){
    body.innerHTML=`${ro?`<div class="note">${ic('lock')}<span>Менять учётную политику может только владелец. Изменения записываются в историю.</span></div>`:''}
    <div class="box"><h3>Функции<span class="grow"></span>${ro?'':`<button class="btn sm" id="pol-quiz" title="Вопросы о том, как вы работаете: по ответам включатся нужные модули">${ic('list','sm')}${ORG.onboard&&ORG.onboard.done?'Пройти опросник заново':'Пройти опросник'}</button>`}</h3><span class="hint" style="margin-top:-4px">Отключённая функция пропадает из меню, вкладок, полей и уведомлений, но данные не удаляются: при повторном включении всё вернётся. Основные модули — «Главная», «Контрагенты», «Отчеты для сдачи», «Сотрудники», «Справочники», «Моя организация», «Мой профиль» и «База знаний» — включены всегда.</span>${FEATURES.map(([k,l,h,dep])=>{const fi=(KBUI.features||{})[k]||{};const art=fi.art&&kbArts().find(a=>a.id===fi.art);return `<label class="check-row" data-feat-row="${k}"><input type="checkbox" class="sw" data-feat="${k}" ${feat(k)?'checked':''} ${ro?'disabled':''}><span class="grow"><b>${esc(l)}</b><div class="hint">${esc(h)}${dep?` · требует «${esc(FEATURES.find(f=>f[0]===dep[0])[1])}»`:''}</div>${fi.benefit?`<div class="hint">Что даёт: ${esc(fi.benefit)}${art?` · <button type="button" class="linkbtn" data-feat-art="${art.id}">Подробнее</button>`:''}</div>`:''}</span></label>${k==='cppage'&&feat(k)?pgPolHtml(ro):''}`}).join('')}</div>
    ${feat('tasks')?`<div class="box"><h3>Задачи</h3><label class="check-row"><input type="checkbox" class="sw" id="pol-tconf" ${ORG.taskConfirm!==false?'checked':''} ${ro?'disabled':''}><span class="grow"><b>Задачи требуют подтверждения</b><div class="hint">В новой задаче переключатель «Требуется подтверждение» сразу включён, постановщик может его снять. У уже поставленных задач признак не меняется.</div></span></label></div>`:''}
    <div class="box"><h3>Отчёты</h3><label class="check-row"><input type="checkbox" class="sw" id="pol-rconf" ${repConfOn()?'checked':''} ${ro?'disabled':''}><span class="grow"><b>Сдача отчётов требует подтверждения</b><div class="hint">Отчёт, отмеченный «Сдан», ждёт подтверждения старшего бухгалтера — сотрудника с правом «Подтверждать сдачу отчётов»; тот подтверждает сдачу или возвращает отчёт «На исправление» с причиной. Если выключить, «Сдан» станет окончательной отметкой.</div></span></label>${repConfOn()?`<div class="form">${fld('Напомнить о неподтверждённой сдаче через, дней',inp('pol-wd',ORG.waitDays||3,`inputmode="numeric" ${ro?'disabled':''}`),{id:'pol-wd',hint:'Сотрудникам с правом «Подтверждать сдачу отчётов» — в Telegram'})}</div>`:''}${feat('taxpay')?`<label class="check-row"><input type="checkbox" class="sw" id="pol-payfirst" ${ORG.payFirst!==false?'checked':''} ${ro?'disabled':''}><span class="grow"><b>Сдача отчёта только после оплаты</b><div class="hint">У отчётов «Сдача + уплата» с суммой к уплате больше 0 «Сдан» ставится, когда налог оплачен полностью или частично: «Указать сумму» → «Принять деньги» → «Отметить оплаченным» → «Сдан». Если контрагент оплатил налог сам — «Оплатил контрагент сам» в окне оплаты.</div></span></label>`:''}</div>
    <div class="box"><h3>Напоминания о сроках по умолчанию</h3><div class="row">${ORG.remind.map((d,i)=>`<span class="chip"><span>за ${d} ${plural(d,'день','дня','дней')}</span>${ro?'':`<button data-rd="${i}" aria-label="Убрать">${ic('x','sm')}</button>`}</span>`).join('')}${ro?'':`<input class="inp" id="rd-add" style="width:96px" inputmode="numeric" placeholder="+ день">`}<span class="pill green">${ic('lock')}в день срока — всегда</span></div><span class="hint">Этот набор получают новые подключённые виды отчётов. Для отдельного вида дни меняются в «Справочники → Виды отчётов». Отключить напоминание в день срока нельзя.</span></div>
    ${(()=>{const h=HIST.filter(x=>x.ent==='org'&&x.id==='policy').slice().reverse();return `<div class="box"><h3>История изменений учётной политики · ${h.length}</h3>${h.length?`<ul class="tl">${h.slice(0,20).map(x=>`<li><span class="t">${fmtD(x.at.slice(0,10))}<br>${x.at.slice(11)}</span><span>${esc(x.what)}<br><span class="w">${esc(whoName(x.who))}</span></span></li>`).join('')}</ul>`:'<span class="faint">Изменений пока не было</span>'}</div>`})()}`;
    body.onchange=e=>{const x=e.target;if(x.id==='pol-rconf')return repConfSet(x);if(x.id==='pol-payfirst'){ORG.payFirst=x.checked;log('org','policy',`Сдача отчёта только после оплаты: ${x.checked?'включено':'выключено'}`);refreshAll();toast(x.checked?'«Сдан» — только после оплаты налога':'«Сдан» можно ставить до оплаты');return}if(x.id==='pol-wd'){const n=+x.value;if(!setErr(body,'pol-wd',Number.isInteger(n)&&n>=1&&n<=30?'':'От 1 до 30 дней')){x.value=ORG.waitDays||3;return}ORG.waitDays=n;log('org','policy',`Напоминание о неподтверждённой сдаче: через ${n} дн.`);toast('Сохранено');return}if(x.dataset.pgPol){const k=x.dataset.pgPol,a=new Set(ORG.pageSec||[]);x.checked?a.add(k):a.delete(k);ORG.pageSec=PG_SECS.map(s=>s[0]).filter(s=>a.has(s));log('org','policy',`Страница контрагента: раздел «${PG_SECS.find(s=>s[0]===k)[1]}» ${x.checked?'показывается':'не показывается'}`);toast('Сохранено');return}if(x.id==='pol-tconf'){ORG.taskConfirm=x.checked;log('org','policy',`Задачи требуют подтверждения: ${x.checked?'включено':'выключено'}`);renderPage();toast(x.checked?'Новые задачи будут требовать подтверждения':'Новые задачи закрываются сразу после «Выполнена»');return}if(!x.dataset.feat)return;const k=x.dataset.feat;
      if(!x.checked){const need=FEATURES.filter(f=>f[3]&&f[3].includes(k)&&feat(f[0]));if(need.length){x.checked=true;toast(`Сначала отключите «${need[0][1]}» — она работает только вместе с этой функцией`,'alert',true);return}}
      else{const f=FEATURES.find(f=>f[0]===k);if(f[3]){const off=f[3].filter(d=>!feat(d));if(off.length){x.checked=false;toast(`Сначала включите «${FEATURES.find(z=>z[0]===off[0])[1]}»`,'alert',true);return}}}
      ORG.features[k]=x.checked;if(x.checked){ORG.featOn=ORG.featOn||{};ORG.featOn[k]=TODAY}ckBase();log('org','policy',`${x.checked?'Включена':'Отключена'} функция «${FEATURES.find(f=>f[0]===k)[1]}»`);refreshAll();
      // При включении — окно «Функция включена» с «Пройти урок»
      if(x.checked)featOnDlg(k);else toast(`${FEATURES.find(f=>f[0]===k)[1]}: отключено`)};
    body.onclick=e=>{const a=e.target.closest('[data-feat-art]');if(a){e.preventDefault();kbArtDlg(KB_ARTS.find(z=>z.id===a.dataset.featArt));return}if(e.target.closest('#pol-quiz'))welcomeOpen({quiz:true})};
    $$('[data-rd]',body).forEach(b=>b.onclick=()=>{ORG.remind.splice(+b.dataset.rd,1);log('org','policy','Дни напоминаний: за '+(ORG.remind.join(', ')||'—')+' дн.');renderPage();ckHit('remind')});const ra=$('#rd-add',body);if(ra)ra.onkeydown=e=>{if(e.key==='Enter'){const n=+ra.value;if(n>0&&n<=60&&!ORG.remind.includes(n)){ORG.remind.push(n);ORG.remind.sort((a,b)=>b-a);log('org','policy','Дни напоминаний: за '+ORG.remind.join(', ')+' дн.');renderPage();ckHit('remind');toast('Набор дней сохранён')}}};
    return}
  const fs=allFiles();const used=fs.reduce((a,f)=>a+(f.size||0),0);
  body.innerHTML=`<div class="box" id="org-storage"><h3>Хранилище файлов</h3><div class="row"><span class="grow">Занято <b>${fmtSize(used)}</b> · файлов: ${fs.length}</span><span class="hint">Ограничение на один файл — 20 МБ</span></div></div><div class="box"><h3>Общие</h3><div class="form">${fld('Часовой пояс',sel('st-tz',['Asia/Bishkek (UTC+6)','Asia/Almaty (UTC+5)','Asia/Tashkent (UTC+5)','Asia/Dushanbe (UTC+5)','Europe/Moscow (UTC+3)'],ORG.tz,ro?'disabled':''),{id:'st-tz',hint:'«Сегодня» и «эта неделя» считаются по нему'})}${fld('Роль по умолчанию для новых сотрудников',sel('st-role',ROLES.filter(r=>r.id!=='owner').map(r=>[r.id,r.name]),ORG.defaultRole,ro?'disabled':''),{id:'st-role'})}</div></div>
  <div class="box"><h3>Напоминания в Telegram</h3>${feat('telegram')?`<label class="check-row"><input type="checkbox" class="sw" id="st-rep" ${ORG.overdueRepeat?'checked':''} ${ro?'disabled':''}><span class="grow">Повторять при просрочке каждый день<div class="hint">Ответственному, главному бухгалтеру и владельцу — пока отчёт не сдан</div></span></label>
  <div class="form">${fld('Еженедельная сводка, понедельник',inp('st-dg',ORG.digest,`type="time" ${ro?'disabled':''}`),{id:'st-dg'})}</div><span class="hint">Все напоминания одному человеку за день собираются в одно сообщение.</span>`:`<div class="note">${ic('info')}<span>Напоминания в Telegram отключены в учётной политике.</span></div>`}</div>
  ${ro?'':`<div class="row"><div class="grow"></div><button class="btn cta" id="st-save">Сохранить настройки</button></div>`}`;
  const sv=$('#st-save',body);if(sv)sv.onclick=()=>{ORG.defaultRole=val(body,'st-role');if($('#st-rep',body)){ORG.overdueRepeat=$('#st-rep',body).checked;ORG.digest=val(body,'st-dg')}log('org','settings','Изменены настройки');toast('Настройки сохранены')};
}

